//! Installing the quotient primitives the way Lean's kernel does: only over
//! an `Eq` that has exactly the shape their types assume.
//!
//! # Why
//!
//! The quotient primitives are kernel-BUILT, not checked: `Quot.lift`'s and
//! `Quot.sound`'s types mention `Eq` BY NAME (`quot.rs`, `make_eq_type`), and
//! nothing re-derives them. [`Environment::init_quot`] installs them over
//! whatever the environment calls `Eq` — or over no `Eq` at all, so that an
//! `Eq` admitted afterwards gives `Quot.sound` its meaning. A replay that
//! installs the quotient first and admits an imported cone's `Eq` later thus
//! lets that cone choose what `Quot.sound` asserts: `Eq a b := False` turns
//! the (counted) axiom `Quot.sound` into a proof of `False`, and so does an
//! `Eq` with no constructor (recheck-closure verification, round 23).
//!
//! Lean's `add_quot` (`src/kernel/quot.cpp`, `quot_consts::check_eq_type`)
//! refuses to install the quotient unless the environment ALREADY holds an
//! inductive `Eq` with one universe parameter, type
//! `{α : Sort u} → α → α → Prop`, and exactly one constructor of type
//! `∀ {α : Sort u} (a : α), @Eq α a a`. [`Environment::add_quot`] is that
//! check followed by [`Environment::init_quot`]. An `Eq` of that shape,
//! admitted as an inductive family, is the identity type whatever its
//! parameter/index split, because its eliminator is REGENERATED by the kernel
//! from exactly that constructor.

use super::Environment;
use crate::expr::{Expr, ExprKind};
use crate::level::Level;
use crate::name::Name;
use crate::quot::names as quotient_names;

impl Environment {
    /// Install the quotient primitives after Lean's `check_eq_type`.
    ///
    /// Idempotent: when the primitives are already installed this returns
    /// `Ok(())` without re-checking, because whatever installed them owns
    /// that environment's `Eq` (a consumer's own base; see the caller).
    ///
    /// # Errors
    ///
    /// A message naming the first way the environment's `Eq` differs from the
    /// one Lean's `add_quot` requires, or an occupied primitive name. Nothing is installed.
    pub fn add_quot(&mut self) -> Result<(), String> {
        if self.has_quot() {
            return Ok(());
        }
        self.check_eq_for_quot()?;
        // Installation replaces constant records. Check every name before any
        // insertion so declarations checked against an earlier binding stay valid.
        for name in [
            &*quotient_names::QUOT,
            &*quotient_names::QUOT_MK,
            &*quotient_names::QUOT_LIFT,
            &*quotient_names::QUOT_IND,
            &*quotient_names::QUOT_SOUND,
        ] {
            if self.get_const(name).is_some() {
                return Err(format!(
                    "the quotient primitive name `{name}` is already declared"
                ));
            }
        }
        self.init_quot();
        Ok(())
    }

    /// Whether the quotient primitives are installed.
    #[must_use]
    pub fn quot_installed(&self) -> bool {
        self.has_quot()
    }

    /// Lean's `quot_consts::check_eq_type`, over this environment.
    ///
    /// Binder info is not compared (Lean's `expr` equality ignores it); every
    /// other part of the two types is compared structurally.
    ///
    /// # Errors
    ///
    /// The first deviation from the required shape.
    pub fn check_eq_for_quot(&self) -> Result<(), String> {
        let eq_name = Name::from_string("Eq");
        let Some(eq) = self.get_inductive(&eq_name) else {
            return Err(
                "the environment does not hold an inductive type `Eq` (Lean's add_quot \
                 requires it before the quotient is installed)"
                    .to_string(),
            );
        };
        let [u] = eq.level_params.as_slice() else {
            return Err(format!(
                "`Eq` has {} universe parameters, expected 1",
                eq.level_params.len()
            ));
        };
        let [refl_name] = eq.constructor_names.as_slice() else {
            return Err(format!(
                "`Eq` has {} constructors, expected 1",
                eq.constructor_names.len()
            ));
        };
        let sort_u = Expr::sort(Level::param(u.clone()));
        let prop = Expr::sort(Level::zero());
        // {α : Sort u} → α → α → Prop
        let expected_eq_type = Expr::pi(
            crate::expr::BinderInfo::Implicit,
            sort_u.clone(),
            Expr::pi(
                crate::expr::BinderInfo::Default,
                Expr::bvar(0),
                Expr::pi(crate::expr::BinderInfo::Default, Expr::bvar(1), prop),
            ),
        );
        if !same_modulo_binder_info(&eq.type_, &expected_eq_type) {
            return Err("`Eq` does not have type `{α : Sort u} → α → α → Prop`".to_string());
        }
        let Some(refl) = self.get_constructor(refl_name) else {
            return Err(format!(
                "`Eq`'s constructor `{refl_name}` is not registered"
            ));
        };
        // ∀ {α : Sort u} (a : α), @Eq.{u} α a a
        let eq_u = Expr::const_(eq_name, vec![Level::param(u.clone())]);
        let expected_refl_type = Expr::pi(
            crate::expr::BinderInfo::Implicit,
            sort_u,
            Expr::pi(
                crate::expr::BinderInfo::Default,
                Expr::bvar(0),
                Expr::app(
                    Expr::app(Expr::app(eq_u, Expr::bvar(1)), Expr::bvar(0)),
                    Expr::bvar(0),
                ),
            ),
        );
        if !same_modulo_binder_info(&refl.type_, &expected_refl_type) {
            return Err(format!(
                "`Eq`'s constructor `{refl_name}` does not have type \
                 `∀ {{α : Sort u}} (a : α), @Eq α a a`"
            ));
        }
        Ok(())
    }
}

impl Environment {
    /// Check the equality family and the constant records used to type a proof about it.
    pub(crate) fn check_equality_premise(&self) -> Result<(), String> {
        self.check_eq_for_quot()?;
        self.check_premise_records(&Name::from_string("Eq"))
    }

    /// What an Ax0 axiom's statement names must mean (R143). The kernel's
    /// canonical `propext`, `Classical.choice` and quotient primitives are
    /// compared by name and statement, but a statement names `Iff`, `Eq` and
    /// `Nonempty` BY NAME, and those mean whatever this environment declares
    /// under them: `def Nonempty := fun _ => ∀ p : Prop, p → p` makes the
    /// canonical `Classical.choice` prove `∀ p : Prop, p`. So each premise
    /// must be the inductive Lean's `Init` declares, of exactly the shape
    /// the axiom assumes (and, as for `Eq` under [`Self::add_quot`], an
    /// inductive of that shape is that predicate whatever its parameter /
    /// index split, because its eliminator is regenerated by the kernel from
    /// its one constructor): `propext` needs `Iff` and `Eq`,
    /// `Classical.choice` needs `Nonempty`, a quotient primitive needs `Eq`.
    /// Any other name has no premise here.
    ///
    /// # Errors
    ///
    /// The first premise that is missing, not an inductive, or of another
    /// shape.
    pub fn check_foundation_premises(&self, axiom: &Name) -> Result<(), String> {
        if super::axiom_audit::name_has_components(axiom, "propext") {
            self.check_equality_premise()?;
            self.check_iff_for_propext()
        } else if super::axiom_audit::name_has_components(axiom, "Classical.choice") {
            self.check_nonempty_for_choice()
        } else if crate::quot::is_quot_name(axiom) {
            self.check_equality_premise()
        } else {
            Ok(())
        }
    }

    /// `structure Iff (a b : Prop) : Prop where intro :: (mp : a → b) (mpr :
    /// b → a)`: no universe parameter, type `Prop → Prop → Prop`, one
    /// constructor of type `∀ {a b : Prop}, (a → b) → (b → a) → Iff a b`.
    ///
    /// # Errors
    ///
    /// The first deviation.
    pub fn check_iff_for_propext(&self) -> Result<(), String> {
        let iff = Name::from_string("Iff");
        let (ind, ctor) = self.one_ctor_inductive(&iff, 0)?;
        let prop = Expr::sort(Level::zero());
        let arrow = |a: Expr, b: Expr| Expr::pi(crate::expr::BinderInfo::Default, a, b);
        let expected = arrow(prop.clone(), arrow(prop.clone(), prop.clone()));
        if !same_modulo_binder_info(&ind.type_, &expected) {
            return Err("`Iff` does not have type `Prop → Prop → Prop`".to_string());
        }
        // Binders a, b, mp, mpr.
        let expected_ctor = Expr::pi(
            crate::expr::BinderInfo::Implicit,
            prop.clone(),
            Expr::pi(
                crate::expr::BinderInfo::Implicit,
                prop,
                arrow(
                    arrow(Expr::bvar(1), Expr::bvar(1)),
                    arrow(
                        arrow(Expr::bvar(1), Expr::bvar(3)),
                        Expr::app(
                            Expr::app(Expr::const_(iff, vec![]), Expr::bvar(3)),
                            Expr::bvar(2),
                        ),
                    ),
                ),
            ),
        );
        if !same_modulo_binder_info(&ctor.type_, &expected_ctor) {
            return Err(format!(
                "`Iff`'s constructor `{}` does not have type \
                 `∀ {{a b : Prop}}, (a → b) → (b → a) → Iff a b`",
                ctor.name
            ));
        }
        Ok(())
    }

    /// `class inductive Nonempty (α : Sort u) : Prop | intro (val : α)`: one
    /// universe parameter, type `Sort u → Prop`, one constructor of type
    /// `∀ {α : Sort u} (val : α), Nonempty α`.
    ///
    /// # Errors
    ///
    /// The first deviation.
    pub fn check_nonempty_for_choice(&self) -> Result<(), String> {
        let nonempty = Name::from_string("Nonempty");
        let (ind, ctor) = self.one_ctor_inductive(&nonempty, 1)?;
        let u = Level::param(ind.level_params[0].clone());
        let sort_u = Expr::sort(u.clone());
        let expected = Expr::pi(
            crate::expr::BinderInfo::Default,
            sort_u.clone(),
            Expr::sort(Level::zero()),
        );
        if !same_modulo_binder_info(&ind.type_, &expected) {
            return Err("`Nonempty` does not have type `Sort u → Prop`".to_string());
        }
        let expected_ctor = Expr::pi(
            crate::expr::BinderInfo::Implicit,
            sort_u,
            Expr::pi(
                crate::expr::BinderInfo::Default,
                Expr::bvar(0),
                Expr::app(Expr::const_(nonempty, vec![u]), Expr::bvar(1)),
            ),
        );
        if !same_modulo_binder_info(&ctor.type_, &expected_ctor) {
            return Err(format!(
                "`Nonempty`'s constructor `{}` does not have type \
                 `∀ {{α : Sort u}} (val : α), Nonempty α`",
                ctor.name
            ));
        }
        Ok(())
    }

    /// `name` is an inductive with `levels` universe parameters and exactly
    /// one registered constructor, and the constant records the checker reads
    /// for both agree with the inductive records.
    fn one_ctor_inductive(
        &self,
        name: &Name,
        levels: usize,
    ) -> Result<
        (
            &crate::inductive::InductiveVal,
            &crate::inductive::ConstructorVal,
        ),
        String,
    > {
        let Some(ind) = self.get_inductive(name) else {
            return Err(format!(
                "the environment does not hold an inductive type `{name}`"
            ));
        };
        if ind.level_params.len() != levels {
            return Err(format!(
                "`{name}` has {} universe parameters, expected {levels}",
                ind.level_params.len()
            ));
        }
        let [ctor_name] = ind.constructor_names.as_slice() else {
            return Err(format!(
                "`{name}` has {} constructors, expected 1",
                ind.constructor_names.len()
            ));
        };
        let Some(ctor) = self.get_constructor(ctor_name) else {
            return Err(format!(
                "`{name}`'s constructor `{ctor_name}` is not registered"
            ));
        };
        self.check_premise_records(name)?;
        Ok((ind, ctor))
    }

    /// The constant records of the inductive `name` and of its constructors
    /// carry no value and the inductive records' own types and universe
    /// parameters (the checker infers a constant's type from its constant
    /// record).
    fn check_premise_records(&self, name: &Name) -> Result<(), String> {
        let Some(ind) = self.get_inductive(name) else {
            return Err(format!(
                "the environment does not hold an inductive type `{name}`"
            ));
        };
        let mut records: Vec<(&Name, &[Name], &Expr)> =
            vec![(&ind.name, ind.level_params.as_slice(), &ind.type_)];
        for c in &ind.constructor_names {
            let Some(ctor) = self.get_constructor(c) else {
                return Err(format!("`{name}`'s constructor `{c}` is not registered"));
            };
            if ctor.inductive_name != *name {
                return Err(format!(
                    "`{c}` is registered as a constructor of another type"
                ));
            }
            records.push((&ctor.name, ctor.level_params.as_slice(), &ctor.type_));
        }
        for (n, levels, type_) in records {
            match self.get_const(n) {
                Some(info)
                    if info.value.is_none()
                        && info.level_params.as_slice() == levels
                        && info.type_ == *type_ => {}
                _ => {
                    return Err(format!(
                        "`{n}`'s constant record does not agree with its inductive record"
                    ))
                }
            }
        }
        Ok(())
    }
}

/// Structural equality that ignores binder info, as Lean's `expr ==` does.
/// Any node kind other than the ones an `Eq` signature is built from falls
/// back to full equality.
fn same_modulo_binder_info(a: &Expr, b: &Expr) -> bool {
    match (&a.kind, &b.kind) {
        (ExprKind::Pi(ba, ta, xa), ExprKind::Pi(bb, tb, xb))
        | (ExprKind::Lam(ba, ta, xa), ExprKind::Lam(bb, tb, xb)) => {
            ba.mult == bb.mult && same_modulo_binder_info(ta, tb) && same_modulo_binder_info(xa, xb)
        }
        (ExprKind::App(fa, xa), ExprKind::App(fb, xb)) => {
            same_modulo_binder_info(fa, fb) && same_modulo_binder_info(xa, xb)
        }
        _ => a == b,
    }
}

